#!/usr/bin/env bash
# PreToolUse guard for Edit / Write / MultiEdit / NotebookEdit. Enforces the file rules in
# CLAUDE.md mechanically, so they hold even when a session has not read it:
#
#   data/fixtures/**            -> denied (generated by the seeded generator: pnpm gen:data)
#   runs/sample-run.jsonl       -> denied (generated by a run: pnpm demo, then copy)
#   ../LICENSE, LICENSE         -> denied (agreed by both owners)
#   .env, .env.* (not example)  -> denied (secrets; document names in .env.example)
#   .wallet/**, *keypair*.json  -> denied (devnet keys are made by pnpm wallet:setup)
#   pnpm-lock.yaml              -> denied (run pnpm install)
#
# Hooks run under Git Bash on Windows, which ships without jq, so the path is pulled out with grep.
set -u

# Every run of backslashes becomes one forward slash, whether the path arrived JSON-escaped
# (C:\\x) or not (C:\x).
to_slashes() { printf '%s' "$1" | sed 's#\\\{1,\}#/#g'; }
to_lower() { printf '%s' "$1" | tr '[:upper:]' '[:lower:]'; }

input=$(cat)

# The first "file_path" / "notebook_path" key is tool_input's own: it precedes the file content,
# which may itself contain the same text.
path=$(printf '%s' "$input" \
  | grep -oE '"(file_path|notebook_path)"[[:space:]]*:[[:space:]]*"[^"]*"' \
  | head -n1 \
  | sed 's/^"[a-z_]*"[[:space:]]*:[[:space:]]*"\(.*\)"$/\1/')
[ -n "$path" ] || exit 0

# Collapse "/./" and "dir/../" so ../LICENSE and the like cannot slip past the match.
normalize() {
  printf '%s' "$1" | sed -e ':a' -e 's#/\./#/#g' -e 's#/[^/][^/]*/\.\./#/#' -e 't a'
}

path=$(normalize "$(to_slashes "$path")")
dir=$(to_slashes "${CLAUDE_PROJECT_DIR:-$PWD}")
dir=${dir%/}
root=${dir%/*}

decide() {
  printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"%s","permissionDecisionReason":"%s"}}\n' "$1" "$2"
  exit 0
}

# Windows paths are case-insensitive, and the drive letter's case varies between sources.
lower_path=$(to_lower "$path")
lower_dir=$(to_lower "$dir")
lower_root=$(to_lower "$root")

case "$lower_path" in
  "$lower_root"/license | "$lower_dir"/license)
    decide deny "LICENSE is the all-rights-reserved license both owners agreed on. Do not change it."
    ;;
  */pnpm-lock.yaml)
    decide deny "The lockfile is generated. Change package.json (after asking), then run pnpm install."
    ;;
esac

[[ $lower_path == "$lower_dir"/* ]] || exit 0
rel=${path:${#dir}+1}

case "$rel" in
  .env.example)
    ;;
  .env | .env.*)
    decide deny "$rel holds secrets. Document variable names in .env.example; the user fills in .env."
    ;;
  .wallet/* | *keypair*.json)
    decide deny "Wallet keys are generated by pnpm wallet:setup and never written by hand or committed."
    ;;
  data/fixtures/*)
    decide deny "data/fixtures/ is generated. Change scripts/gen-data.ts (or the trap list) and run: pnpm gen:data"
    ;;
  runs/sample-run.jsonl)
    decide deny "The sample run log is generated: run pnpm demo and copy the new log over it, so every number stays real."
    ;;
esac

exit 0
